    id: "beyond-iv", cat: "music", title: "Beyond IV", alt: "Beyond · 真的爱你母爱颂歌", year: 1989, region: "中国香港",
    summary: "Beyond第四张粤语专辑，收录传世金曲《真的爱你》，以摇滚形式歌颂母爱，四人各唱一段加家驹标志性吼叫，感动无数听众。同时包含《爆裂都市》《逝去日子》等多元曲目，展现乐队在商业与艺术间的平衡能力，是其主流化转折点。",
