    summary: "张国荣复出后最具艺术野心的专辑，由C.Y.Kong与林夕共同打造。融合Trip-hop、电子与戏剧化编排，《红》《偷情》《有心人》等曲目探讨性别、欲望与身份认同，声音表现力达至化境，是其超越流行偶像成为文化符号的关键作品。",
    review: "艺术性极高、情感浓烈，适合深度审美体验；风格前卫暗黑，非粉丝或难接受。建议配合「跨越97演唱会」影像理解其舞台与录音的互文关系，完整领略张国荣晚期美学。",
