    summary: "陈奕迅英皇时期代表作，以「沟通」为核心概念贯穿全碟。收录《Shall We Talk》《孤独探戈》等名曲，林夕与黄伟文从亲情、爱情、社会关系多维度切入，编曲精致且情绪递进清晰，是其早期概念专辑中最完整的一次实践。",
