    summary: "陈奕迅近年最具实验性的国语专辑，由Jerald Chan操刀制作。融合Synth-pop、Funk与电子元素，《放》《之外》等曲目打破传统情歌框架，声线处理大胆前卫，展现其在功成名就后仍勇于突破舒适区的艺术自觉。",
