    id: "jay-chou-yiran-fantexi", cat: "music", title: "依然范特西", alt: "周杰伦 · 自我致敬与风格总结", year: 2006, region: "中国台湾",
    summary: "周杰伦第七张专辑，以《夜的第七章》《听妈妈的话》《菊花台》等曲目回顾并整合前作风格。制作精良、曲目多元，既有暗黑叙事也有温情告白，虽创新力度不及早期，却是其创作体系最完整的阶段性总结，标志「周式美学」进入成熟稳定期。",
    review: "制作精良、曲目均衡，适合系统了解周杰伦风格谱系；突破性减弱，老乐迷或觉惊喜不足。推荐对比《范特西》聆听，体会五年间同一创作者如何在重复与进化间寻找平衡。",
    pros: ["风格体系完整", "制作精良均衡", "曲目多元丰富", "阶段总结意义"], cons: ["突破性减弱"],
    tags: ["周杰伦", "国语流行", "R&B", "中国风"],
